-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 2
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 2 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 02', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 02 (10 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-PRATICA-AULA-02.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Separe os itens em hardware e software.', 0.5, 'Hardware: processador Intel Core i5, memória RAM de 8 GB, SSD de 480 GB, placa-mãe. Software: Windows 11, sistema WMS, planilha eletrônica, leitor de PDF.', 'Nota cheia: os oito itens certos. Metade: seis ou sete certos. Zero: cinco ou menos.'),
      (v_atividade, 1, 2, 'Explique a diferença entre hardware e software usando a comparação do "corpo" e da "mente" e por que um não funciona sem o outro.', 0.5, 'Hardware é a parte física (o "corpo"): peças, cabos e circuitos que se pode tocar. Software é a parte lógica (a "mente"): programas e instruções que dizem à máquina o que fazer. O hardware sem software fica parado, e o software precisa do hardware para ser executado.', 'Nota cheia: diferença correta + dependência entre os dois. Metade: só a diferença. Zero: definições trocadas.'),
      (v_atividade, 2, 1, 'Explique a função da CPU e da memória RAM, dizendo o que significa a RAM ser volátil.', 0.5, 'CPU: o "cérebro", busca e executa as instruções e faz os cálculos (ULA, UC, registradores). RAM: guarda temporariamente os dados dos programas em uso, com acesso rápido. Volátil: perde tudo quando o computador é desligado.', 'Nota cheia: função da CPU + função da RAM + volatilidade. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 2, 2, 'Explique a função da placa-mãe e do SSD no computador.', 0.5, 'Placa-mãe: interliga todos os componentes por barramentos (soquete da CPU, slots, chipset). SSD: armazenamento permanente dos arquivos e do sistema, com memória Flash, rápido e sem peças móveis.', 'Nota cheia: as duas funções corretas. Metade: uma correta. Zero: nenhuma.'),
      (v_atividade, 3, 1, 'Compare HDD e SSD em velocidade, resistência a impactos e custo.', 0.5, 'SSD: muito mais rápido (até 10 vezes), resistente a impactos (sem peças móveis), mais caro por TB. HDD: mais lento, vulnerável a impactos (pratos e agulha), mais barato por TB.', 'Nota cheia: compara os três aspectos. Metade: dois aspectos. Zero: um ou comparação errada.'),
      (v_atividade, 3, 2, 'Explique por que os 4 GB de RAM também deixam o computador lento e indique qual troca você recomendaria primeiro, justificando.', 0.5, 'Com pouca RAM, o sistema usa memória virtual no disco (que é lento, ainda mais num HDD) para rodar o WMS e a planilha juntos, e o computador trava. Recomendação: trocar o HDD por SSD (melhora a inicialização e todo o acesso a disco) ou aumentar a RAM para 8 GB, desde que justificado pelos sintomas (inicialização lenta → SSD; travar com vários programas → RAM).', 'Nota cheia: explica a memória virtual/falta de RAM + recomenda uma troca com justificativa coerente. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 4, 1, 'Classifique cada periférico como de entrada, de saída ou de entrada e saída.', 0.6, 'Entrada: leitor de código de barras, teclado, scanner de notas fiscais. Saída: impressora de etiquetas, monitor. Entrada e saída: coletor de dados com tela touch, pen drive, headset.', 'Nota cheia: sete ou oito certos. Metade: cinco ou seis certos. Zero: quatro ou menos.'),
      (v_atividade, 4, 2, 'Indique o tipo de conexão mais adequado para ligar o monitor e o cabo de rede do computador e para que serve a porta USB.', 0.4, 'Monitor: HDMI ou DisplayPort (vídeo e áudio digital). Rede: RJ-45 (Ethernet). USB: conexão universal de periféricos com transmissão de dados e alimentação elétrica (leitor, pen drive, teclado).', 'Nota cheia: as três respostas certas. Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 5, 1, 'Descreva, em ordem, as três verificações para o leitor de código de barras (hardware, driver e configuração do sistema).', 0.5, '1) Hardware: conferir o cabo e a porta, testar em outra porta USB. 2) Driver: verificar no gerenciador de dispositivos se o leitor aparece com alerta e instalar/atualizar o driver. 3) Configuração do SO: conferir se o dispositivo está habilitado e configurado.', 'Nota cheia: as três verificações na ordem. Metade: três fora de ordem ou duas certas. Zero: uma ou nenhuma.'),
      (v_atividade, 5, 2, 'Explique como corrigir o problema da impressora e o cuidado correto ao retirar o pen drive.', 0.5, 'Impressora: definir a impressora de etiquetas como padrão (ou escolhê-la na hora de imprimir) e conferir antes de imprimir. Pen drive: esperar a cópia terminar e usar "Ejetar / Remover hardware com segurança" antes de retirar, para não corromper o arquivo.', 'Nota cheia: as duas soluções. Metade: uma. Zero: nenhuma.'),
      (v_atividade, 6, 1, 'Explique o que o sistema operacional faz no computador (cite pelo menos duas funções).', 0.5, 'O SO faz a mediação entre usuário, programas e hardware. Funções: gerenciar processos (tempo de CPU), gerenciar a memória RAM, controlar arquivos e discos, controlar dispositivos/drivers, oferecer a interface gráfica.', 'Nota cheia: papel de mediação + duas funções. Metade: uma função ou só o papel. Zero: sem relação.'),
      (v_atividade, 6, 2, 'Classifique os três equipamentos da empresa pelo tipo de SO (desktop, servidor ou móvel) e explique a diferença entre SO proprietário e de código aberto.', 0.5, 'Windows do escritório: desktop. Linux do banco de dados do WMS: servidor. Android dos coletores: móvel. Proprietário: código fechado, mantido por empresa, geralmente pago (Windows). Código aberto: código disponível para estudo e adaptação, geralmente gratuito (Linux).', 'Nota cheia: três classificações + diferença proprietário/aberto. Metade: só um dos dois completo. Zero: nenhum.'),
      (v_atividade, 7, 1, 'Escreva o atalho de teclado do Windows para cada uma das cinco ações.', 0.5, 'Abrir o explorador: Windows + E. Copiar e colar: Ctrl + C e Ctrl + V. Renomear: F2. Voltar para o WMS: Alt + Tab. Bloquear a tela: Windows + L.', 'Nota cheia: quatro ou cinco atalhos certos. Metade: dois ou três. Zero: um ou nenhum.'),
      (v_atividade, 7, 2, 'Explique o que são a barra de tarefas e a barra de endereço do explorador de arquivos e por que bloquear a tela é importante.', 0.5, 'Barra de tarefas: mostra os programas abertos e a bandeja com relógio e rede. Barra de endereço: mostra o caminho da pasta atual (ex.: C:\VALESUL\EXPEDICAO). Bloquear a tela impede que outra pessoa use o computador e veja ou altere dados com o seu usuário quando você sai.', 'Nota cheia: as duas barras + motivo do bloqueio. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 8, 1, 'Escreva a árvore de diretórios do setor, a partir de C:\, com pastas e subpastas por tipo de documento e ano.', 0.5, 'Ex.: C:\VALESUL\EXPEDICAO\2026\ com subpastas ROMANEIOS, PLANILHAS, NOTAS-FISCAIS, RELATORIOS (e, se quiser, meses 2026-09, 2026-10). Hierarquia da raiz para o específico, sem acentos.', 'Nota cheia: árvore a partir de C:\ com pasta do setor, ano e subpastas por tipo. Metade: estrutura incompleta (sem ano ou sem tipos). Zero: sem estrutura.'),
      (v_atividade, 8, 2, 'Renomeie os três arquivos seguindo as boas práticas de nomenclatura (data AAAA-MM-DD, sem acentos e espaços, com versão) e diga a extensão adequada de cada um.', 0.5, 'Ex.: 2026-10-02_Procedimento_Expedicao_v01.docx; 2026-10-02_Controle_Cargas_v01.xlsx; 2026-10-02_Romaneio_Pedido4587_v02.pdf. Extensões: DOCX (texto editável), XLSX (planilha), PDF (documento final).', 'Nota cheia: três nomes no padrão (data, descrição, versão, sem acento/espaço) com extensões certas. Metade: padrão parcial ou um nome errado. Zero: nomes genéricos.'),
      (v_atividade, 9, 1, 'Explique como encontrar todos os PDFs usando a pesquisa do sistema (curinga e filtro por data).', 0.4, 'No explorador, na pasta do setor, digitar *.pdf na caixa de pesquisa para localizar todos os PDFs e usar o filtro "Data de modificação" para setembro de 2026 (ou ordenar por data).', 'Nota cheia: curinga *.pdf + filtro por data. Metade: só um dos dois. Zero: procurar arquivo por arquivo.'),
      (v_atividade, 9, 2, 'Descreva, em ordem, os passos para compactar os 40 arquivos e anexá-los ao e-mail, com o nome do pacote, e o que a auditoria deve fazer ao receber.', 0.6, '1) Selecionar os 40 PDFs (de preferência copiados para uma pasta). 2) Botão direito → Compactar para ZIP. 3) Renomear o pacote com data e assunto (ex.: 2026-09_Relatorios_Expedicao.zip). 4) Anexar ao e-mail, citando o anexo no corpo. A auditoria usa "Extrair tudo" para abrir os arquivos.', 'Nota cheia: passos na ordem + nome padronizado + "Extrair tudo". Metade: passos certos sem nome ou sem extrair. Zero: enviar os 40 arquivos soltos.'),
      (v_atividade, 10, 1, 'Indique qual falha provavelmente está acontecendo, pelos sintomas, e cite duas ações de manutenção preventiva.', 0.5, 'Superaquecimento (ventoinha barulhenta, poeira, sem ventilação, trava sob carga). Manutenção preventiva: limpar a poeira com cuidado (sem panos úmidos ou químicos), deixar o gabinete em local ventilado e afastado da parede, usar nobreak/filtro de linha.', 'Nota cheia: superaquecimento + duas ações. Metade: só o diagnóstico ou só as ações. Zero: diagnóstico errado sem ações.'),
      (v_atividade, 10, 2, 'Explique o risco de a planilha existir só nesse computador e como deve ser a rotina de backup.', 0.5, 'Se o disco falhar, houver vírus ou o computador for roubado, a planilha se perde sem recuperação. Rotina de backup: cópias periódicas (ex.: diárias) em outro local — disco externo e/ou nuvem —, conferindo se a cópia abre (ex.: regra 3-2-1).', 'Nota cheia: risco + rotina periódica em outro local. Metade: só um dos dois. Zero: sem relação.');
end $$;
